//! HTTP proxy server for sandboxed network access.//!//! This proxy runs on the host and handles all network requests from containers.//! It validates requests against the allowlist and injects credentials when needed.//!//! ```text//! Container ──► http_proxy=host.docker.internal:PORT ──► This Proxy ──► Internet//!                                                             │//!                                                             ├─► Validate domain//!                                                             ├─► Inject credentials//!                                                             └─► Log requests//! ```use std::convert::Infallible;use std::net::SocketAddr;use std::sync::Arc;use bytes::Bytes;use http_body_util::{BodyExt, Empty, Full, combinators::BoxBody};use hyper::server::conn::http1;use hyper::service::service_fn;use hyper::{Method, Request, Response, StatusCode};use hyper_util::rt::TokioIo;use tokio::net::{TcpListener, TcpStream};use tokio::sync::RwLock;use crate::sandbox::error::{Result, SandboxError};use crate::sandbox::proxy::policy::{NetworkDecision, NetworkPolicyDecider, NetworkRequest};use crate::secrets::CredentialLocation;/// State shared across proxy connections.struct ProxyState {    /// Policy decider for network requests.    decider: Arc<dyn NetworkPolicyDecider>,    /// Credential resolver (maps secret names to values).    credential_resolver: Arc<dyn CredentialResolver>,    /// Shared HTTP client for forwarding requests.    http_client: reqwest::Client,    /// Request counter for logging.    request_count: std::sync::atomic::AtomicU64,    /// Whether the proxy is running.    running: std::sync::atomic::AtomicBool,}/// Resolves secret names to their values.#[async_trait::async_trait]pub trait CredentialResolver: Send + Sync {    /// Get the value of a secret by name.    async fn resolve(&self, name: &str) -> Option<String>;}/// A credential resolver that uses environment variables.pub struct EnvCredentialResolver;#[async_trait::async_trait]impl CredentialResolver for EnvCredentialResolver {    async fn resolve(&self, name: &str) -> Option<String> {        std::env::var(name).ok()    }}/// A credential resolver that returns nothing (for testing).pub struct NoCredentialResolver;#[async_trait::async_trait]impl CredentialResolver for NoCredentialResolver {    async fn resolve(&self, _name: &str) -> Option<String> {        None    }}/// HTTP proxy server.pub struct HttpProxy {    state: Arc<ProxyState>,    addr: RwLock<Option<SocketAddr>>,    shutdown_tx: RwLock<Option<tokio::sync::oneshot::Sender<()>>>,}impl HttpProxy {    /// Create a new HTTP proxy.    pub fn new(        decider: Arc<dyn NetworkPolicyDecider>,        credential_resolver: Arc<dyn CredentialResolver>,    ) -> Self {        Self {            state: Arc::new(ProxyState {                decider,                credential_resolver,                http_client: reqwest::Client::new(),                request_count: std::sync::atomic::AtomicU64::new(0),                running: std::sync::atomic::AtomicBool::new(false),            }),            addr: RwLock::new(None),            shutdown_tx: RwLock::new(None),        }    }    /// Start the proxy server on the given port (0 for auto-assign).    pub async fn start(&self, port: u16) -> Result<SocketAddr> {        let listener = TcpListener::bind(format!("127.0.0.1:{}", port))            .await            .map_err(|e| SandboxError::ProxyError {                reason: format!("failed to bind: {}", e),            })?;        let addr = listener            .local_addr()            .map_err(|e| SandboxError::ProxyError {                reason: format!("failed to get local addr: {}", e),            })?;        *self.addr.write().await = Some(addr);        let (shutdown_tx, mut shutdown_rx) = tokio::sync::oneshot::channel();        *self.shutdown_tx.write().await = Some(shutdown_tx);        self.state            .running            .store(true, std::sync::atomic::Ordering::SeqCst);        let state = self.state.clone();        tokio::spawn(async move {            tracing::info!("Sandbox proxy started on {}", addr);            loop {                tokio::select! {                    accept_result = listener.accept() => {                        match accept_result {                            Ok((stream, _)) => {                                let io = TokioIo::new(stream);                                let state = state.clone();                                tokio::spawn(async move {                                    let service = service_fn(move |req| {                                        let state = state.clone();                                        async move { handle_request(req, state).await }                                    });                                    if let Err(e) = http1::Builder::new()                                        .preserve_header_case(true)                                        .title_case_headers(true)                                        .serve_connection(io, service)                                        .with_upgrades()                                        .await                                    {                                        tracing::debug!("Proxy connection error: {}", e);                                    }                                });                            }                            Err(e) => {                                tracing::error!("Proxy accept error: {}", e);                            }                        }                    }                    _ = &mut shutdown_rx => {                        tracing::debug!("Sandbox proxy shutting down");                        break;                    }                }            }            state                .running                .store(false, std::sync::atomic::Ordering::SeqCst);        });        Ok(addr)    }    /// Stop the proxy server.    pub async fn stop(&self) {        if let Some(tx) = self.shutdown_tx.write().await.take() {            let _ = tx.send(());        }    }    /// Get the address the proxy is listening on.    pub async fn addr(&self) -> Option<SocketAddr> {        *self.addr.read().await    }    /// Check if the proxy is running.    pub fn is_running(&self) -> bool {        self.state.running.load(std::sync::atomic::Ordering::SeqCst)    }    /// Get the number of requests handled.    pub fn request_count(&self) -> u64 {        self.state            .request_count            .load(std::sync::atomic::Ordering::SeqCst)    }}/// Handle an incoming proxy request.async fn handle_request(    req: Request<hyper::body::Incoming>,    state: Arc<ProxyState>,) -> std::result::Result<Response<BoxBody<Bytes, Infallible>>, Infallible> {    state        .request_count        .fetch_add(1, std::sync::atomic::Ordering::SeqCst);    // Handle CONNECT method for HTTPS tunneling    if req.method() == Method::CONNECT {        return Ok(handle_connect(req, state).await);    }    // For HTTP requests, validate and forward    let uri = req.uri().to_string();    let method = req.method().to_string();    let network_req = match NetworkRequest::from_url(&method, &uri) {        Some(r) => r,        None => {            tracing::warn!("Proxy: invalid URL: {}", uri);            return Ok(error_response(                StatusCode::BAD_REQUEST,                "Invalid URL".to_string(),            ));        }    };    // Make policy decision    let decision = state.decider.decide(&network_req).await;    match decision {        NetworkDecision::Deny { reason } => {            tracing::info!("Proxy: blocked {} {} - {}", method, uri, reason);            Ok(error_response(StatusCode::FORBIDDEN, reason))        }        NetworkDecision::Allow | NetworkDecision::AllowWithCredentials { .. } => {            // Forward the request            forward_request(req, decision, state).await        }    }}/// Handle CONNECT method for HTTPS tunneling.////// Establishes a bidirectional TCP tunnel between the client and the target host./// Returns 200 OK to signal the client to begin TLS over the upgraded connection.////// NOTE: Credential injection is not possible through CONNECT tunnels since the proxy/// cannot inspect or modify TLS-encrypted traffic without MITM. Containers that need/// authenticated HTTPS should fetch credentials via the orchestrator's/// `GET /worker/{id}/credentials` endpoint and set them as environment variables.
